// spec: specs/placement-reading.md (2.1) · кейсы PRD-02, PRD-05 · запасной путь (двойное нажатие + REST)
// seed: tests/seed.parent.spec.ts
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  createChild,
  fetchPlacementAttempts,
  handoverToIntro,
  passReadingToResults,
  qaChildName,
  readingScreens,
  trackSupabaseRest,
} from './reading.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe('Стартовый тест чтения — одна попытка, продолжение, сбои, 390 (autotest-writer)', () => {
  test('Одна попытка: два обновления C1 и двойное нажатие «מתחילים!» — 1 строка placement_attempts; после C3 writing_status = pending @desktop @data #8bf5a8', async ({ asUser }, testInfo) => {
    test.setTimeout(5 * 60_000); // лимит на 3 отрывка, не пауза
    const page = await asUser('parent');
    const rest = trackSupabaseRest(page);
    const s = readingScreens(page);
    const name = qaChildName();

    // 1. Создать ребёнка, передать устройство → C1 (попытка создаётся при открытии C1)
    const childId = await createChild(page, name, '2018');
    annotateCleanup(testInfo, name, childId);
    await handoverToIntro(page, childId, name);

    // 2. Обновить C1 дважды
    for (let i = 0; i < 2; i++) {
      await page.reload();
      await expect(s.introTitle).toBeVisible();
    }

    // 3. Двойное нажатие «מתחילים!» → «קטע 1»
    await s.start.dblclick();
    await expect(s.passage(1)).toBeVisible();

    // 4. placement_attempts ребёнка — ровно 1 строка (тикет «בלי ליצור ניסיון כפול»; AC4; G1)
    const before = await fetchPlacementAttempts(page, rest, childId);
    expect(before, 'после 2 обновлений и двойного нажатия должна быть ровно 1 попытка').toHaveLength(1);

    // 5. Пройти 3 отрывка самооценкой («בסדר») до /assessment/results
    await passReadingToResults(page, 'בסדר');

    // 6. По-прежнему 1 строка (тот же id), writing_status = pending (AC4; #be58fd)
    const after = await fetchPlacementAttempts(page, rest, childId);
    expect(after, 'после C3 должна остаться ровно 1 попытка').toHaveLength(1);
    expect(after[0].id, 'попытка после C3 — та же строка').toBe(before[0].id);
    expect(after[0], 'в placement_attempts нет колонки writing_status — остановиться и сообщить').toHaveProperty('writing_status');
    expect(after[0].writing_status).toBe('pending');
  });
});
